<?php
require_once 'functions.php';require_login();$id=uid();$month=$_POST['month_key']??$_GET['month']??date('Y-m');$msg='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$amt=filter_var($_POST['amount']??'',FILTER_VALIDATE_FLOAT);if(!preg_match('/^\d{4}-(0[1-9]|1[0-2])$/',$month)||$amt===false||$amt<=0)$err='Choose a valid month and budget greater than zero.';else{$s=$pdo->prepare('INSERT INTO budgets(user_id,month_key,amount) VALUES(?,?,?) ON DUPLICATE KEY UPDATE amount=VALUES(amount)');$s->execute([$id,$month,$amt]);$msg='Budget updated successfully.';}}
$s=$pdo->prepare('SELECT amount FROM budgets WHERE user_id=? AND month_key=?');$s->execute([$id,$month]);$r=$s->fetch();$budget=(float)($r['amount']??0);$s=$pdo->prepare("SELECT COALESCE(SUM(amount),0) spent FROM transactions WHERE user_id=? AND type='expense' AND DATE_FORMAT(transaction_date,'%Y-%m')=?");$s->execute([$id,$month]);$spent=(float)$s->fetch()['spent'];$remain=$budget-$spent;$pct=$budget>0?$spent/$budget*100:0;start_page('Budgets','budget.php');?>
<div class="page-intro"><div><h1>Your budget, your pace.</h1><p>Give your spending a plan that works for you.</p></div><span class="date-chip">◷ <?=e($month)?></span></div><?php if($msg):?><div class="alert success"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="alert danger"><?=e($err)?></div><?php endif;?><section class="panel"><div class="panel-head"><div><h2>Monthly spending plan</h2><p>Choose a month and set a comfortable limit.</p></div><span class="round-icon">◷</span></div><form method="post" class="form-grid"><label>Month<input type="month" name="month_key" value="<?=e($month)?>" required></label><label>Budget amount (<?=e(csym())?>)<input type="number" name="amount" min=".01" step=".01" value="<?=e((string)($r['amount']??''))?>" required></label><div class="actions"><button class="primary">Save budget →</button></div></form></section><section class="metrics"><article class="metric purple"><div>Planned budget <span>◈</span></div><strong><?=money($budget)?></strong><small>For <?=e($month)?></small></article><article class="metric peach"><div>Spent so far <span>↘</span></div><strong><?=money($spent)?></strong><small>Recorded expenses</small></article><article class="metric mint"><div>Remaining <span>✦</span></div><strong class="<?=$remain<0?'red':''?>"><?=money($remain)?></strong><small>Budget minus expenses</small></article></section><section class="panel"><div class="panel-head"><div><h2>Spending progress</h2><p>Check in before the month gets away from you.</p></div><b><?=number_format($pct,1)?>%</b></div><div class="progress big"><span style="width:<?=min(100,max(0,$pct))?>%"></span></div><?php if(!$budget):?><div class="alert">Set a monthly budget to start tracking progress.</div><?php elseif($pct>=100):?><div class="alert danger">You’ve reached or passed your budget.</div><?php elseif($pct>=80):?><div class="alert warning">You’ve used at least 80% of your budget.</div><?php else:?><div class="alert success">Looking good! You’re within your planned budget.</div><?php endif;?></section><?php end_page();?>
